package main

import (
	"crypto/ed25519"
	"encoding/hex"
	"encoding/json"
	"log"
	"net/http"
	"os"
	"time"

	"example.com/eg/internal/attest"
	"example.com/eg/internal/cit"
	"example.com/eg/internal/gateway"
	"example.com/eg/internal/store"
)

type Server struct {
	Store       *store.Store
	Priv        ed25519.PrivateKey
	Pub         ed25519.PublicKey
	ReceiptPriv ed25519.PrivateKey
	ReceiptPub  ed25519.PublicKey
}

func main() {
	// Load or generate demo keys
	privHex := os.Getenv("EG_ED25519_PRIV_HEX")
	receiptPrivHex := os.Getenv("EG_RECEIPT_PRIV_HEX")
	var priv ed25519.PrivateKey
	var pub ed25519.PublicKey
	var rpriv ed25519.PrivateKey
	var rpub ed25519.PublicKey

	if privHex == "" {
		_, pk, _ := ed25519.GenerateKey(nil)
		priv = pk
		pub = pk.Public().(ed25519.PublicKey)
		log.Println("Generated demo EG keypair")
	} else {
		b, _ := hex.DecodeString(privHex)
		priv = ed25519.PrivateKey(b)
		pub = priv.Public().(ed25519.PublicKey)
	}

	if receiptPrivHex == "" {
		_, pk, _ := ed25519.GenerateKey(nil)
		rpriv = pk
		rpub = pk.Public().(ed25519.PublicKey)
		log.Println("Generated demo receipt keypair")
	} else {
		b, _ := hex.DecodeString(receiptPrivHex)
		rpriv = ed25519.PrivateKey(b)
        rpub = rpriv.Public().(ed25519.PublicKey)
	}

	st := store.NewStore()
	// Seed demo policy and known payees
	st.Policy.DefaultMoneyDailyCapPreVerified = 200
	st.Policy.NonDelegable = map[string]bool{"close_account": true}
	st.AddKnownPayee("payee_789") // ACME for happy path

	s := &Server{Store: st, Priv: priv, Pub: pub, ReceiptPriv: rpriv, ReceiptPub: rpub}

	mux := http.NewServeMux()

	// /mint_cit
	mux.HandleFunc("/mint_cit", func(w http.ResponseWriter, r *http.Request) {
		if r.Method != "POST" {
			http.Error(w, "method", http.StatusMethodNotAllowed)
			return
		}
		var req cit.MintRequest
		if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
			http.Error(w, "bad json", 400); return
		}
		if err := req.Validate(); err != nil {
			http.Error(w, "invalid: "+err.Error(), 401); return
		}
		token, exp, jti, err := cit.MintCIT(s.Pub, s.Priv, &req)
		if err != nil {
			http.Error(w, "mint fail", 500); return
		}
		// Track jti reserved window (optional)
		s.JTISeen[jti] = time.Now()
		_ = json.NewEncoder(w).Encode(map[string]any{"cit": token, "exp": exp})
	})

	// /attest
	mux.HandleFunc("/attest", func(w http.ResponseWriter, r *http.Request) {
		if r.Method != "POST" { http.Error(w, "method", 405); return }
		var a attest.A3S
		if err := json.NewDecoder(r.Body).Decode(&a); err != nil {
			http.Error(w, "bad json", 400); return
		}
		tt, expiry, err := s.Store.AcceptAttestation(&a)
		if err != nil {
			http.Error(w, "invalid attestation: "+err.Error(), 400); return
		}
		_ = json.NewEncoder(w).Encode(map[string]any{"trust_tier": tt, "expires_at": expiry.Format(time.RFC3339)})
	})

	// /execute
	mux.HandleFunc("/execute", func(w http.ResponseWriter, r *http.Request) {
		if r.Method != "POST" { http.Error(w, "method", 405); return }
		var env gateway.ExecuteEnvelope
		if err := json.NewDecoder(r.Body).Decode(&env); err != nil {
			http.Error(w, "bad json", 400); return
		}
		res := gateway.Execute(r.Context(), s.Store, s.Pub, s.ReceiptPriv, &env)
		status := 200
		switch res.Status {
		case "allowed": status = 200
		case "deny": status = 403
		case "block": status = 409
		default: status = 400
		}
		w.Header().Set("Content-Type", "application/json")
		_ = json.NewEncoder(w).Encode(res)
	})

	// /revoke
	mux.HandleFunc("/revoke", func(w http.ResponseWriter, r *http.Request) {
		if r.Method != "POST" { http.Error(w, "method", 405); return }
		var req struct{
			JTI  string `json:"jti"`
			CID  string `json:"cid"`
			FreezeForSec int `json:"freeze_for_sec"`
			Reason string `json:"reason"`
		}
		if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
			http.Error(w, "bad json", 400); return
		}
		if req.JTI != "" {
			s.Store.RevokeJTI(req.JTI, req.Reason)
		}
		if req.CID != "" && req.FreezeForSec >= 60 {
			s.Store.FreezeCompartment(req.CID, time.Duration(req.FreezeForSec)*time.Second, req.Reason)
		}
		_ = json.NewEncoder(w).Encode(map[string]string{"status":"ok"})
	})

	addr := ":8080"
	log.Printf("EG listening on %s", addr)
	log.Fatal(http.ListenAndServe(addr, mux))
}

internal/cit/cit.go
package cit

import (
	"bytes"
	"crypto/ed25519"
	"crypto/rand"
	"encoding/base64"
	"encoding/json"
	"errors"
	"fmt"
	"time"
)

type MintRequest struct {
	Sub string `json:"sub"`
	CID string `json:"cid"` // money|health|legal|comms|data
	Act string `json:"act"`
	Res map[string]any `json:"res"`
	Lim struct {
		Amount   float64 `json:"amount"`
		Currency string  `json:"currency"`
		TTL      int     `json:"ttl"`
	} `json:"lim"`
	Ctx string `json:"ctx"` // hash of summary
	KFP string `json:"kfp"`
	DGB struct {
		DeviceID string `json:"device_id"`
		GeoHash  string `json:"geo_hash"`
	} `json:"dgb"`
	Aud string `json:"aud"`
}

func (m *MintRequest) Validate() error {
	if m.Sub=="" || m.CID=="" || m.Act=="" || m.Ctx=="" || m.KFP=="" || m.Lim.TTL<=0 {
		return errors.New("missing required")
	}
	switch m.CID {
	case "money","health","legal","comms","data":
	default:
		return errors.New("bad cid")
	}
	return nil
}

type citPayload struct {
	Sub string `json:"sub"`
	CID string `json:"cid"`
	Act string `json:"act"`
	Res map[string]any `json:"res"`
	Lim map[string]any `json:"lim"`
	Ctx string `json:"ctx"`
	JTI string `json:"jti"`
	Aud string `json:"aud"`
	Iat int64  `json:"iat"`
	Exp int64  `json:"exp"`
	KFP string  `json:"kfp"`
	DGB map[string]string `json:"dgb,omitempty"`
}

func b64url(b []byte) string {
	return base64.RawURLEncoding.EncodeToString(b)
}

func MintCIT(pub ed25519.PublicKey, priv ed25519.PrivateKey, req *MintRequest) (string, int64, string, error) {
	now := time.Now().Unix()
	exp := now + int64(req.Lim.TTL)
	jti := randJTI()
	pl := citPayload{
		Sub: req.Sub, CID:req.CID, Act:req.Act, Res:req.Res,
		Lim: map[string]any{"amount":req.Lim.Amount,"currency":req.Lim.Currency,"ttl":req.Lim.TTL},
		Ctx: req.Ctx, JTI: jti, Aud: req.Aud, Iat: now, Exp: exp, KFP: req.KFP,
		DGB: map[string]string{"device_id": req.DGB.DeviceID, "geo_hash": req.DGB.GeoHash},
	}
	hdr := map[string]any{"alg":"EdDSA","typ":"CIT"}
	hb, _ := json.Marshal(hdr)
	pb, _ := json.Marshal(pl)
	sig := ed25519.Sign(priv, pb)
	token := fmt.Sprintf("%s.%s.%s", b64url(hb), b64url(pb), b64url(sig))
	return token, exp, jti, nil
}

func VerifyCIT(pub ed25519.PublicKey, token string) (*citPayload, error) {
	parts := bytes.Split([]byte(token), []byte{'.'})
	if len(parts)!=3 { return nil, errors.New("bad token") }
	pb, err := base64.RawURLEncoding.DecodeString(string(parts[1])); if err!=nil { return nil, err }
	sb, err := base64.RawURLEncoding.DecodeString(string(parts[2])); if err!=nil { return nil, err }
	if !ed25519.Verify(pub, pb, sb) { return nil, errors.New("bad sig") }
	var pl citPayload
	if err := json.Unmarshal(pb, &pl); err!=nil { return nil, err }
	if time.Now().Unix()>pl.Exp { return nil, errors.New("expired") }
	return &pl, nil
}

func randJTI() string {
	b := make([]byte, 16)
	_, _ = rand.Read(b)
	return hexify(b)
}

func hexify(b []byte) string {
	const hextable = "0123456789abcdef"
	out := make([]byte, len(b)*2)
	for i, v := range b {
		out[i*2] = hextable[v>>4]
		out[i*2+1] = hextable[v&0x0f]
	}
	return string(out)
}

internal/attest/attest.go
package attest

import (
	"errors"
	"time"
)

type Org struct {
	Name string `json:"name"`
	Jurisdiction string `json:"jurisdiction"`
	RegID string `json:"reg_id"`
}
type ModelClass struct {
	Type string `json:"type"` // llm|rules|hybrid
	Version string `json:"version"`
	SafetyHash string `json:"safety_hash"`
}
type Key struct {
	Pub string `json:"pub"`
	Alg string `json:"alg"`
	Rotation string `json:"rotation"`
}
type Assurance struct {
	AuditRefs []string `json:"audit_refs"`
	LastPentest string `json:"last_pentest"` // YYYY-MM-DD
}
type A3S struct {
	AIID string `json:"ai_id"`
	Org Org `json:"org"`
	ModelClass ModelClass `json:"model_class"`
	ExecScope []string `json:"exec_scope"`
	Assurance Assurance `json:"assurance"`
	Key Key `json:"key"`
	TS string `json:"ts"`
}

func Validate(a *A3S) error {
	if a.AIID=="" || a.Org.Name=="" || a.ModelClass.Type=="" || len(a.ExecScope)==0 || a.Key.Pub=="" || a.TS=="" {
		return errors.New("missing fields")
	}
	switch a.ModelClass.Type {
	case "llm","rules","hybrid":
	default: return errors.New("bad model type")
	}
	return nil
}

func TierFor(a *A3S) (string, time.Time) {
	// Demo heuristic: if org+assurance present and model hybrid/rules, tier=verified else known
	var tier = "known"
	if a.Org.Name!="" && len(a.Assurance.AuditRefs)>0 && (a.ModelClass.Type=="hybrid" || a.ModelClass.Type=="rules") {
		tier = "verified"
	}
	exp := time.Now().Add(24*time.Hour)
	return tier, exp
}

internal/risk/risk.go
package risk

import (
	"strings"
	"time"
)

type Inputs struct {
	FirstTimePayee bool
	AfterHours     bool
	UrgentLanguage bool
	GeoDriftHigh   bool
	TrustTier      string
	Amount         float64
	KnownPayee     bool
}

type Output struct {
	Score   int
	Signals []string
}

func Score(in Inputs) Output {
	score := 0
	sigs := []string{}
	if in.FirstTimePayee { score += 35; sigs = append(sigs, "first_time_payee") }
	now := time.Now()
	if now.Hour()<8 || now.Hour()>19 { score += 15; sigs = append(sigs, "after_hours") }
	if in.UrgentLanguage { score += 25; sigs = append(sigs, "urgent_language") }
	if in.GeoDriftHigh { score += 10; sigs = append(sigs, "geo_drift") }
	if in.TrustTier=="stranger" { score += 10; sigs = append(sigs, "stranger_counterparty") }
	if in.Amount>1000 { score += 10; sigs = append(sigs, "high_amount") }
	return Output{Score: clamp(score,0,100), Signals: sigs}
}

func HasUrgency(text string) bool {
	t := strings.ToLower(text)
	key := []string{"urgent","today only","expedite","immediately","wire now","asap","just for today"}
	for _, k := range key {
		if strings.Contains(t, k) { return true }
	}
	return false
}

func clamp(x,min,max int) int {
	if x<min {return min}
	if x>max {return max}
	return x
}

internal/gateway/execute.go
package gateway

import (
	"context"
	"crypto/ed25519"
	"encoding/json"
	"time"

	"example.com/eg/internal/cit"
	"example.com/eg/internal/risk"
	"example.com/eg/internal/store"
)

type Counterparty struct {
	ID string `json:"id"`
	Attestation map[string]any `json:"attestation"`
	TrustTier string `json:"trust_tier"` // stranger|known|verified|delegated
}

type ExecuteEnvelope struct {
	Action string `json:"action"`
	Resource map[string]any `json:"resource"`
	Parameters map[string]any `json:"parameters"`
	Amount float64 `json:"amount"`
	Currency string `json:"currency"`
	Counterparty Counterparty `json:"counterparty"`
	CIT string `json:"cit"`
	SummaryHash string `json:"summary_hash"`
}

type ExecuteResponse struct {
	Status string `json:"status"` // allowed|deny|block
	Reason string `json:"reason,omitempty"`
	Risk struct {
		Score int `json:"score"`
		Signals []string `json:"signals"`
	} `json:"risk"`
	NextStep map[string]any `json:"next_step,omitempty"`
	Receipt map[string]any `json:"receipt,omitempty"`
}

func Execute(ctx context.Context, s *store.Store, pub ed25519.PublicKey, receiptPriv ed25519.PrivateKey, env *ExecuteEnvelope) ExecuteResponse {
	// Validate CIT
	pl, err := cit.VerifyCIT(pub, env.CIT)
	if err != nil {
		return deny(70, []string{"cit_invalid"}, "CIT_INVALID", nil)
	}
	// Check summary hash match
	if pl.Ctx != env.SummaryHash {
		return deny(60, []string{"ctx_mismatch"}, "CIT_CONTEXT_MISMATCH", nil)
	}
	// Replay protection
	if s.IsRevokedJTI(pl.JTI) || s.SeenJTI(pl.JTI) {
		return deny(80, []string{"jti_replay"}, "JTI_REPLAY", nil)
	}
	s.MarkJTI(pl.JTI)

	// Compartment freeze check
	if s.IsCompartmentFrozen(pl.CID) {
		return block(95, []string{"compartment_frozen"}, "COMPARTMENT_FROZEN")
	}
	// Policy: non-delegable?
	if s.Policy.NonDelegable[env.Action] {
		return block(95, []string{"non_delegable"}, "NON_DELEGABLE_ACTION")
	}

	// Money compartment simple policy
	firstTime := false
	if pl.CID=="money" {
		payee, _ := env.Resource["payee_id"].(string)
		if payee=="" {
			return deny(50, []string{"missing_payee"}, "MISSING_PAYEE", nil)
		}
		firstTime = !s.IsKnownPayee(payee)
	}

	// Risk scoring
	urg := false
	if memo, ok := env.Parameters["memo"].(string); ok {
		urg = risk.HasUrgency(memo)
	}
	rout := risk.Score(risk.Inputs{
		FirstTimePayee: firstTime,
		UrgentLanguage: urg,
		TrustTier: env.Counterparty.TrustTier,
		Amount: env.Amount,
	})

	// Enforce caps (demo)
	if pl.CID=="money" {
		payee, _ := env.Resource["payee_id"].(string)
		verified := s.IsKnownPayee(payee)
		allowed := 0.0
		if verified {
			allowed = float64(s.Policy.DefaultMoneyDailyCapPreVerified)
		}
		if env.Amount > allowed {
			// require live confirm
			return deny(max(rout.Score, 70), append(rout.Signals, "over_cap"), "HIGH_RISK_NEEDS_LIVE_CONFIRM",
				map[string]any{"type":"live_confirm","channel":"mobile_secure_app","expires_in":600})
		}
	}

	// Thresholds: if risk too high, deny
	if rout.Score >= 75 {
		return deny(rout.Score, rout.Signals, "HIGH_RISK_NEEDS_LIVE_CONFIRM",
			map[string]any{"type":"live_confirm","channel":"mobile_secure_app","expires_in":600})
	}

	// Execute (simulate) and log
	rcpt := s.AppendDecisionLog(map[string]any{
		"ts": time.Now().Format(time.RFC3339),
		"action": env.Action,
		"resource": env.Resource,
		"parameters": env.Parameters,
		"amount": env.Amount,
		"currency": env.Currency,
		"jti": pl.JTI,
		"risk": map[string]any{"score": rout.Score, "signals": rout.Signals},
		"outcome": "allow",
	})
	// Sign receipt (demo: sign JSON bytes)
	rb, _ := json.Marshal(rcpt)
	sig := store.Ed25519Sign(receiptPriv, rb)
	rcpt["signature"] = sig

	resp := ExecuteResponse{Status:"allowed"}
	resp.Risk.Score = rout.Score
	resp.Risk.Signals = rout.Signals
	resp.Receipt = map[string]any{
		"id": rcpt["id"],
		"ts": rcpt["ts"],
		"jti": pl.JTI,
		"risk": rcpt["risk"],
		"controls": []string{"CIT_VALID","LIMIT_OK","ATTEST_OK"},
		"signature": sig,
	}
	return resp
}

func deny(score int, signals []string, reason string, next map[string]any) ExecuteResponse {
	resp := ExecuteResponse{Status:"deny", Reason: reason}
	resp.Risk.Score = score
	resp.Risk.Signals = signals
	if next!=nil { resp.NextStep = next }
	return resp
}
func block(score int, signals []string, reason string) ExecuteResponse {
	resp := ExecuteResponse{Status:"block", Reason: reason}
	resp.Risk.Score = score
	resp.Risk.Signals = signals
	return resp
}
func max(a,b int) int { if a>b {return a}; return b }

internal/store/store.go
package store

import (
	"crypto/ed25519"
	"encoding/base64"
	"encoding/json"
	"fmt"
	"os"
	"sync"
	"time"

	"example.com/eg/internal/attest"
)

type Policy struct {
	DefaultMoneyDailyCapPreVerified int
	NonDelegable map[string]bool
}

type Store struct {
	mu sync.Mutex

	Policy Policy

	KnownPayees map[string]bool
	CounterpartyTiers map[string]struct{
		Tier string
		Expires time.Time
	}

	JTISeen map[string]time.Time
	JTIRevoked map[string]string

	CompartmentFrozen map[string]time.Time

	LogFile *os.File
	LogSeq int64
}

func NewStore() *Store {
	lf, _ := os.OpenFile("eg-decisions.log", os.O_CREATE|os.O_WRONLY|os.O_APPEND, 0644)
	return &Store{
		Policy: Policy{DefaultMoneyDailyCapPreVerified:200, NonDelegable: map[string]bool{}},
		KnownPayees: map[string]bool{},
		CounterpartyTiers: map[string]struct{Tier string; Expires time.Time}{},
		JTISeen: map[string]time.Time{},
		JTIRevoked: map[string]string{},
		CompartmentFrozen: map[string]time.Time{},
		LogFile: lf,
		LogSeq: 0,
	}
}

func (s *Store) AddKnownPayee(id string) { s.mu.Lock(); defer s.mu.Unlock(); s.KnownPayees[id]=true }
func (s *Store) IsKnownPayee(id string) bool { s.mu.Lock(); defer s.mu.Unlock(); return s.KnownPayees[id] }

func (s *Store) AcceptAttestation(a *attest.A3S) (string, time.Time, error) {
	if err := attest.Validate(a); err!=nil { return "", time.Time{}, err }
	tier, exp := attest.TierFor(a)
	s.mu.Lock(); s.CounterpartyTiers[a.AIID] = struct{Tier string; Expires time.Time}{tier, exp}; s.mu.Unlock()
	return tier, exp, nil
}

func (s *Store) SeenJTI(jti string) bool { s.mu.Lock(); defer s.mu.Unlock(); _, ok := s.JTISeen[jti]; return ok }
func (s *Store) MarkJTI(jti string) { s.mu.Lock(); s.JTISeen[jti]=time.Now(); s.mu.Unlock() }
func (s *Store) RevokeJTI(jti, reason string) { s.mu.Lock(); s.JTIRevoked[jti]=reason; s.mu.Unlock() }
func (s *Store) IsRevokedJTI(jti string) bool { s.mu.Lock(); defer s.mu.Unlock(); _, ok := s.JTIRevoked[jti]; return ok }

func (s *Store) FreezeCompartment(cid string, d time.Duration, reason string) {
	s.mu.Lock(); defer s.mu.Unlock()
	s.CompartmentFrozen[cid] = time.Now().Add(d)
}
func (s *Store) IsCompartmentFrozen(cid string) bool {
	s.mu.Lock(); defer s.mu.Unlock()
	until, ok := s.CompartmentFrozen[cid]
	if !ok { return false }
	return time.Now().Before(until)
}

func (s *Store) AppendDecisionLog(entry map[string]any) map[string]any {
	s.mu.Lock(); defer s.mu.Unlock()
	s.LogSeq++
	entry["id"] = fmt.Sprintf("rcpt_%06d", s.LogSeq)
	b, _ := json.Marshal(entry)
	_, _ = s.LogFile.Write(append(b, '\n'))
	return entry
}

func Ed25519Sign(priv ed25519.PrivateKey, data []byte) string {
	sig := ed25519.Sign(priv, data)
	return base64.StdEncoding.EncodeToString(sig)
}

web/api.yaml
openapi: 3.1.0
info:
  title: Twin Execution Gateway
  version: 0.1.0
servers:
  - url: http://localhost:8080
paths:
  /mint_cit:
    post:
      summary: Mint a capability-scoped intent token (CIT)
      requestBody:
        required: true
        content:
          application/json:
            schema:
              type: object
              required: [sub, cid, act, res, lim, ctx, kfp, dgb, aud]
              properties:
                sub: { type: string }
                cid: { type: string, enum: [money, health, legal, comms, data] }
                act: { type: string }
                res: { type: object }
                lim:
                  type: object
                  required: [amount, currency, ttl]
                  properties:
                    amount: { type: number }
                    currency: { type: string }
                    ttl: { type: integer }
                ctx: { type: string }
                kfp: { type: string }
                dgb:
                  type: object
                  required: [device_id, geo_hash]
                  properties:
                    device_id: { type: string }
                    geo_hash: { type: string }
                aud: { type: string }
      responses:
        "200":
          description: CIT minted
  /execute:
    post:
      summary: Execute a scoped action with a CIT
      requestBody:
        required: true
        content:
          application/json:
            schema:
              $ref: "#/components/schemas/ExecuteEnvelope"
      responses:
        "200": { description: Allowed }
        "403": { description: Denied; needs live confirm }
        "409": { description: Blocked by policy }
  /revoke:
    post:
      summary: Revoke a CIT or freeze a compartment
      requestBody:
        required: true
        content:
          application/json:
            schema:
              type: object
              oneOf:
                - required: [jti]
                - required: [cid, freeze_for_sec]
              properties:
                jti: { type: string }
                cid: { type: string, enum: [money, health, legal, comms, data] }
                freeze_for_sec: { type: integer, minimum: 60 }
                reason: { type: string }
      responses:
        "200": { description: OK }
  /attest:
    post:
      summary: Present AI-to-AI attestation (A3S)
      requestBody:
        required: true
        content:
          application/json:
            schema:
              $ref: "#/components/schemas/A3S"
      responses:
        "200": { description: Trust tier assigned }
components:
  schemas:
    A3S:
      type: object
      required: [ai_id, org, model_class, exec_scope, assurance, key, ts]
      properties:
        ai_id: { type: string }
        org:
          type: object
          required: [name, jurisdiction, reg_id]
          properties:
            name: { type: string }
            jurisdiction: { type: string }
            reg_id: { type: string }
        model_class:
          type: object
          required: [type, version, safety_hash]
          properties:
            type: { type: string, enum: [llm, rules, hybrid] }
            version: { type: string }
            safety_hash: { type: string }
        exec_scope: { type: array, items: { type: string } }
        assurance:
          type: object
          required: [audit_refs, last_pentest]
          properties:
            audit_refs: { type: array, items: { type: string } }
            last_pentest: { type: string, format: date }
        key:
          type: object
          required: [pub, alg, rotation]
          properties:
            pub: { type: string }
            alg: { type: string }
            rotation: { type: string }
        ts: { type: string, format: date-time }
    ExecuteEnvelope:
      type: object
      required: [action, resource, parameters, cit, counterparty, summary_hash]
      properties:
        action: { type: string }
        resource: { type: object }
        parameters: { type: object }
        amount: { type: number }
        currency: { type: string }
        summary_hash: { type: string }
        cit: { type: string }
        counterparty:
          type: object
          required: [id, attestation, trust_tier]
          properties:
            id: { type: string }
            attestation: { type: object }
            trust_tier: { type: string, enum: [stranger, known, verified, delegated] }

