openapi: 3.1.0
info:
  title: Twin Execution Gateway
  version: 0.1.0
servers:
  - url: http://localhost:8080
paths:
  /mint_cit:
    post:
      summary: Mint a capability-scoped intent token (CIT)
      requestBody:
        required: true
        content:
          application/json:
            schema:
              type: object
              required: [sub, cid, act, res, lim, ctx, kfp, dgb, aud]
              properties:
                sub: { type: string }
                cid: { type: string, enum: [money, health, legal, comms, data] }
                act: { type: string }
                res: { type: object }
                lim:
                  type: object
                  required: [amount, currency, ttl]
                  properties:
                    amount: { type: number }
                    currency: { type: string }
                    ttl: { type: integer }
                ctx: { type: string }
                kfp: { type: string }
                dgb:
                  type: object
                  required: [device_id, geo_hash]
                  properties:
                    device_id: { type: string }
                    geo_hash: { type: string }
                aud: { type: string }
      responses:
        "200":
          description: CIT minted
  /execute:
    post:
      summary: Execute a scoped action with a CIT
      requestBody:
        required: true
        content:
          application/json:
            schema:
              $ref: "#/components/schemas/ExecuteEnvelope"
      responses:
        "200": { description: Allowed }
        "403": { description: Denied; needs live confirm }
        "409": { description: Blocked by policy }
  /revoke:
    post:
      summary: Revoke a CIT or freeze a compartment
      requestBody:
        required: true
        content:
          application/json:
            schema:
              type: object
              oneOf:
                - required: [jti]
                - required: [cid, freeze_for_sec]
              properties:
                jti: { type: string }
                cid: { type: string, enum: [money, health, legal, comms, data] }
                freeze_for_sec: { type: integer, minimum: 60 }
                reason: { type: string }
      responses:
        "200": { description: OK }
  /attest:
    post:
      summary: Present AI-to-AI attestation (A3S)
      requestBody:
        required: true
        content:
          application/json:
            schema:
              $ref: "#/components/schemas/A3S"
      responses:
        "200": { description: Trust tier assigned }
components:
  schemas:
    A3S:
      type: object
      required: [ai_id, org, model_class, exec_scope, assurance, key, ts]
      properties:
        ai_id: { type: string }
        org:
          type: object
          required: [name, jurisdiction, reg_id]
          properties:
            name: { type: string }
            jurisdiction: { type: string }
            reg_id: { type: string }
        model_class:
          type: object
          required: [type, version, safety_hash]
          properties:
            type: { type: string, enum: [llm, rules, hybrid] }
            version: { type: string }
            safety_hash: { type: string }
        exec_scope: { type: array, items: { type: string } }
        assurance:
          type: object
          required: [audit_refs, last_pentest]
          properties:
            audit_refs: { type: array, items: { type: string } }
            last_pentest: { type: string, format: date }
        key:
          type: object
          required: [pub, alg, rotation]
          properties:
            pub: { type: string }
            alg: { type: string }
            rotation: { type: string }
        ts: { type: string, format: date-time }
    ExecuteEnvelope:
      type: object
      required: [action, resource, parameters, cit, counterparty, summary_hash]
      properties:
        action: { type: string }
        resource: { type: object }
        parameters: { type: object }
        amount: { type: number }
        currency: { type: string }
        summary_hash: { type: string }
