+func ledgerKey(sub, payee string) string { return sub + "|" + payee }
+
+// RecordSpend records an allowed spend and prunes >24h entries.
+func (s *Store) RecordSpend(sub, payee string, amt float64, now time.Time) {
+  key := ledgerKey(sub, payee)
+  s.mu.Lock()
+  list := s.spends[key]
+  cutoff := now.Add(-24*time.Hour)
+  kept := list[:0]
+  for _, e := range list {
+    if e.Ts.After(cutoff) { kept = append(kept, e) }
+  }
+  kept = append(kept, spendEntry{Ts: now, Amt: amt})
+  // reassign
+  s.spends[key] = kept
+  s.mu.Unlock()
+}
+
+// SumLast24h returns total amount in last 24h for user/payee.
+func (s *Store) SumLast24h(sub, payee string, now time.Time) float64 {
+  key := ledgerKey(sub, payee)
+  s.mu.Lock(); defer s.mu.Unlock()
+  list := s.spends[key]
+  cutoff := now.Add(-24*time.Hour)
+  total := 0.0
+  for _, e := range list {
+    if e.Ts.After(cutoff) { total += e.Amt }
+  }
+  return total
+}

