+// COSESign creates a COSE_Sign1 (EdDSA) over data (JSON payload) and returns base64 (rawstd) of CBOR bytes.
+func COSESign(priv ed25519.PrivateKey, pub ed25519.PublicKey, contentType string, data []byte) (string, error) {
+	msg := cose.Sign1Message{
+		Protected: cose.ProtectedHeader{
+			cose.HeaderLabelAlgorithm:   cose.AlgorithmEdDSA,
+			cose.HeaderLabelContentType: contentType,
+		},
+		Payload: data,
+	}
+	ck := cose.Key{KTY: cose.KeyTypeOKP, ALG: cose.AlgorithmEdDSA, CRV: cose.EllipticCurveEd25519, D: priv.Seed(), X: pub}
+	signer, err := cose.NewSigner(cose.AlgorithmEdDSA, &ck)
+	if err != nil { return "", err }
+	if err := msg.Sign(rand.Reader, signer); err != nil { return "", err }
+	cborBytes, err := msg.MarshalCBOR()
+	if err != nil { return "", err }
+	return base64.RawStdEncoding.EncodeToString(cborBytes), nil
+}

