5) internal/mtls/bind.go: new helper for ai_id extraction and binding
+++ b/internal/mtls/bind.go
@@ -0,0 +1,68 @@
+package mtls
+
+import (
+	"crypto/x509"
+	"net/url"
+	"os"
+	"strings"
+)
+
+// ExtractAIID extracts an identifier from the client certificate based on env EG_MTLS_AI_ID_FIELD:
+// - "uri": from SAN URIs (preferred default)
+// - "dns": from SAN DNSNames
+// - "cn": from Subject CommonName (fallback/legacy)
+// Returns the first match found per chosen field.
+func ExtractAIID(cert *x509.Certificate) (string, string) {
+	mode := strings.ToLower(os.Getenv("EG_MTLS_AI_ID_FIELD"))
+	if mode == "" { mode = "uri" }
+	switch mode {
+	case "uri":
+		for _, u := range cert.URIs {
+			// Use full URI string or path, depending on your naming. Here we use full string.
+			return u.String(), "uri"
+		}
+		// fallback to CN if no URI
+		if cert.Subject.CommonName != "" {
+			return cert.Subject.CommonName, "cn"
+		}
+	case "dns":
+		if len(cert.DNSNames) > 0 {
+			return cert.DNSNames[0], "dns"
+		}
+		if cert.Subject.CommonName != "" {
+			return cert.Subject.CommonName, "cn"
+		}
+	case "cn":
+		if cert.Subject.CommonName != "" {
+			return cert.Subject.CommonName, "cn"
+		}
+	default:
+		// unknown mode -> default to uri
+		for _, u := range cert.URIs {
+			return u.String(), "uri"
+		}
+		if cert.Subject.CommonName != "" {
+			return cert.Subject.CommonName, "cn"
+		}
+	}
+	return "", mode
+}
+
+// Normalize optionally strips schemes for URI mode if you want to compare only the path/host.
+// For now we do exact string compare. If uri has a scheme, keep it.
+func Normalize(id string, mode string) string {
+	if mode == "uri" {
+		if u, err := url.Parse(id); err == nil && u.Scheme != "" {
+			// Keep full URI string
+			return u.String()
+		}
+	}
+	return id
+}

